#include "SystemArgumentDefinitions\WorldCellSystemsArgs.h"
#include "ArgusLogging.h"

bool WorldCellSystemsArgs::PopulateArguments(ArgusEntity entity)
{
	if (UNLIKELY(!entity))
	{
		return false;
	}

	m_entity = entity;
	m_transformComponent = entity.GetComponent<TransformComponent>();
	m_worldCellComponent = entity.GetComponent<WorldCellComponent>();

	if (!m_entity || !m_transformComponent || !m_worldCellComponent)
	{
		return false;
	}

	return true;
}

bool WorldCellSystemsArgs::AreComponentsValidCheck(const WIDECHAR* functionName) const
{
	if (UNLIKELY(!m_entity || !m_transformComponent || !m_worldCellComponent))
	{
		ArgusLogging::LogInvalidComponentReferences(functionName, ARGUS_NAMEOF(WorldCellSystemsArgs));
		return false;
	}

	return true;
}
